'use strict';

function normalizeWord(raw) {
  let s;
  if (typeof raw === 'string') {
    s = raw;
  } else if (raw === null || raw === undefined) {
    return null;
  } else {
    try {
      s = String(raw);
    } catch (e) {
      return null;
    }
  }

  s = s.trim().toLowerCase();
  // collapse any whitespace run to a single space
  s = s.replace(/\s+/g, ' ');
  // strip anything that isn't a letter, digit, hyphen, or space
  s = s.replace(/[^a-z0-9\- ]/g, '');
  // re-collapse whitespace and trim in case stripping left extra spaces
  s = s.replace(/\s+/g, ' ').trim();

  if (s.length === 0 || s.length > 30) return null;
  return s;
}

function createState() {
  return { counts: {}, total: 0 };
}

function addWord(state, raw) {
  const word = normalizeWord(raw);
  if (word === null) {
    return { state, word: null, error: 'invalid word' };
  }

  const newCounts = Object.assign({}, state.counts);
  newCounts[word] = (newCounts[word] || 0) + 1;

  const newState = {
    counts: newCounts,
    total: state.total + 1,
  };

  return { state: newState, word, error: null };
}

function getCloud(state, opts) {
  const { minSize, maxSize } = Object.assign({ minSize: 12, maxSize: 48 }, opts || {});

  const words = Object.keys(state.counts);
  if (words.length === 0) return [];

  const maxCount = Math.max(...words.map((w) => state.counts[w]));

  const entries = words.map((word) => {
    const count = state.counts[word];
    const size = Math.round(minSize + (maxSize - minSize) * (count / (maxCount || 1)));
    return { word, count, size };
  });

  entries.sort((a, b) => {
    if (b.count !== a.count) return b.count - a.count;
    return a.word < b.word ? -1 : a.word > b.word ? 1 : 0;
  });

  return entries;
}

module.exports = { normalizeWord, createState, addWord, getCloud };

