'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { normalizeWord, createState, addWord, getCloud } = require('./wordcloud.js');

test('normalizeWord trims and lowercases', () => {
  assert.strictEqual(normalizeWord('  Hello  '), 'hello');
  assert.strictEqual(normalizeWord('HeLLo World'), 'hello world');
});

test('normalizeWord collapses internal whitespace', () => {
  assert.strictEqual(normalizeWord('foo    bar'), 'foo bar');
  assert.strictEqual(normalizeWord('foo\t\nbar'), 'foo bar');
});

test('normalizeWord strips disallowed characters but keeps letters, numbers, hyphens', () => {
  assert.strictEqual(normalizeWord('c@t!!'), 'ct');
  assert.strictEqual(normalizeWord('well-known2'), 'well-known2');
  assert.strictEqual(normalizeWord('100% cool!'), '100 cool');
});

test('normalizeWord rejects empty input', () => {
  assert.strictEqual(normalizeWord(''), null);
  assert.strictEqual(normalizeWord('   '), null);
  assert.strictEqual(normalizeWord('!!!'), null);
});

test('normalizeWord rejects overlong input (>30 chars)', () => {
  const long = 'a'.repeat(31);
  assert.strictEqual(normalizeWord(long), null);
  const ok = 'a'.repeat(30);
  assert.strictEqual(normalizeWord(ok), ok);
});

test('normalizeWord rejects non-string, non-coercible input', () => {
  assert.strictEqual(normalizeWord(null), null);
  assert.strictEqual(normalizeWord(undefined), null);
  const bad = { toString() { throw new Error('nope'); } };
  assert.strictEqual(normalizeWord(bad), null);
});

test('normalizeWord accepts coercible non-string input', () => {
  assert.strictEqual(normalizeWord(123), '123');
});

test('createState returns fresh empty state', () => {
  const s1 = createState();
  const s2 = createState();
  assert.deepStrictEqual(s1, { counts: {}, total: 0 });
  s1.counts.foo = 5;
  assert.deepStrictEqual(s2, { counts: {}, total: 0 });
});

test('addWord does not mutate the input state', () => {
  const state = createState();
  const frozenCopy = JSON.parse(JSON.stringify(state));
  addWord(state, 'cat');
  assert.deepStrictEqual(state, frozenCopy);
});

test('addWord accumulates repeated words correctly', () => {
  let state = createState();
  let result = addWord(state, 'cat');
  state = result.state;
  assert.strictEqual(result.word, 'cat');
  assert.strictEqual(state.counts.cat, 1);

  result = addWord(state, 'Cat');
  state = result.state;
  assert.strictEqual(state.counts.cat, 2);
  assert.strictEqual(state.total, 2);

  result = addWord(state, 'dog');
  state = result.state;
  assert.strictEqual(state.counts.cat, 2);
  assert.strictEqual(state.counts.dog, 1);
  assert.strictEqual(state.total, 3);
});

test('addWord returns error for invalid words without changing counts', () => {
  const state = createState();
  const result = addWord(state, '!!!');
  assert.strictEqual(result.error, 'invalid word');
  assert.strictEqual(result.word, null);
  assert.strictEqual(result.state, state);
  assert.deepStrictEqual(result.state.counts, {});
});

test('getCloud returns empty array for empty state', () => {
  const state = createState();
  assert.deepStrictEqual(getCloud(state), []);
});

test('getCloud sorts by count descending with alphabetical tiebreak', () => {
  let state = createState();
  ['banana', 'apple', 'cherry', 'apple', 'banana', 'apple'].forEach((w) => {
    state = addWord(state, w).state;
  });
  // apple: 3, banana: 2, cherry: 1
  const cloud = getCloud(state);
  assert.deepStrictEqual(cloud.map((e) => e.word), ['apple', 'banana', 'cherry']);

  let state2 = createState();
  ['zebra', 'apple'].forEach((w) => {
    state2 = addWord(state2, w).state;
  });
  const cloud2 = getCloud(state2);
  // both count 1, alphabetical tiebreak
  assert.deepStrictEqual(cloud2.map((e) => e.word), ['apple', 'zebra']);
});

test('getCloud produces sizes within bounds and monotonic with count', () => {
  let state = createState();
  for (let i = 0; i < 5; i++) state = addWord(state, 'popular').state;
  state = addWord(state, 'rare').state;

  const cloud = getCloud(state, { minSize: 10, maxSize: 50 });
  const popular = cloud.find((e) => e.word === 'popular');
  const rare = cloud.find((e) => e.word === 'rare');

  assert.ok(popular.size >= 10 && popular.size <= 50);
  assert.ok(rare.size >= 10 && rare.size <= 50);
  assert.ok(popular.size > rare.size);
  assert.strictEqual(popular.size, 50); // max count maps to maxSize
});

test('getCloud uses default opts when none provided', () => {
  let state = createState();
  state = addWord(state, 'solo').state;
  const cloud = getCloud(state);
  assert.strictEqual(cloud[0].size, 48); // only word -> max count -> maxSize default
});

const test = require('node:test');
const assert = require('node:assert');
const http = require('node:http');
const server = require('./server.js');

function startServer() {
  return new Promise((resolve) => {
    server.listen(0, () => {
      resolve(server.address().port);
    });
  });
}

function request(port, options, body) {
  return new Promise((resolve, reject) => {
    const req = http.request(
      Object.assign({ hostname: 'localhost', port }, options),
      (res) => {
        let data = '';
        res.on('data', (chunk) => {
          data += chunk;
        });
        res.on('end', () => {
          resolve({ statusCode: res.statusCode, headers: res.headers, body: data });
        });
      }
    );
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

let port;

test.before(async () => {
  port = await startServer();
});

test.after(() => {
  server.close();
});

