'use strict';

// Cap on the number of distinct words tracked at once. Once this many
// distinct words exist, adding a brand-new word evicts the tracked word
// with the lowest count, breaking ties by picking the one that was first
// seen longest ago. This keeps the state structure bounded even if a
// client submits many unique strings.
const MAX_DISTINCT_WORDS = 1000;

function normalizeWord(raw) {
  let s;
  if (typeof raw === 'string') {
    s = raw;
  } else if (raw === null || raw === undefined) {
    return null;
  } else {
    try {
      s = String(raw);
    } catch (e) {
      return null;
    }
  }

  s = s.trim().toLowerCase();
  // collapse any whitespace run to a single space
  s = s.replace(/\s+/g, ' ');
  // strip anything that isn't a letter, digit, hyphen, or space
  s = s.replace(/[^a-z0-9\- ]/g, '');
  // re-collapse whitespace and trim in case stripping left extra spaces
  s = s.replace(/\s+/g, ' ').trim();

  if (s.length === 0 || s.length > 30) return null;
  return s;
}

function createState() {
  return { counts: {}, total: 0, order: [] };
}

function addWord(state, raw) {
  const word = normalizeWord(raw);
  if (word === null) {
    return { state, word: null, error: 'invalid word' };
  }

  const counts = Object.assign({}, state.counts);
  const order = state.order.slice();

  const isNewWord = !Object.prototype.hasOwnProperty.call(counts, word);
  counts[word] = (counts[word] || 0) + 1;
  if (isNewWord) order.push(word);

  const total = state.total + 1;

  if (isNewWord && order.length > MAX_DISTINCT_WORDS) {
    // Evict the tracked word with the lowest count; among ties, the one
    // that was first seen longest ago (earliest in `order`).
    let minCount = Infinity;
    for (const w of order) {
      if (counts[w] < minCount) minCount = counts[w];
    }
    let evictIndex = -1;
    for (let i = 0; i < order.length; i++) {
      if (counts[order[i]] === minCount) {
        evictIndex = i;
        break;
      }
    }
    const evictWord = order[evictIndex];
    delete counts[evictWord];
    order.splice(evictIndex, 1);
  }

  const newState = { counts, total, order };

  return { state: newState, word, error: null };
}

function getCloud(state, opts) {
  const { minSize, maxSize } = Object.assign({ minSize: 12, maxSize: 48 }, opts || {});

  const words = Object.keys(state.counts);
  if (words.length === 0) return [];

  const maxCount = Math.max(...words.map((w) => state.counts[w]));

  const entries = words.map((word) => {
    const count = state.counts[word];
    const size = Math.round(minSize + (maxSize - minSize) * (count / (maxCount || 1)));
    return { word, count, size };
  });

  entries.sort((a, b) => {
    if (b.count !== a.count) return b.count - a.count;
    return a.word < b.word ? -1 : a.word > b.word ? 1 : 0;
  });

  return entries;
}

module.exports = { normalizeWord, createState, addWord, getCloud };

