// --- Rate limiting for /submit -------------------------------------------
// Simple sliding-window limiter keyed by client IP: at most RATE_LIMIT_MAX
// submissions per RATE_LIMIT_WINDOW_MS. Prevents a single visitor (or a
// script) from flooding /submit and hammering every connected SSE client
// with broadcasts, which would otherwise be a denial-of-service against the
// demo itself.
const RATE_LIMIT_WINDOW_MS = 10 * 1000;
const RATE_LIMIT_MAX = 15;
const submissionLog = new Map(); // ip -> array of timestamps

function isRateLimited(ip) {
  const now = Date.now();
  let timestamps = submissionLog.get(ip) || [];
  timestamps = timestamps.filter((t) => now - t < RATE_LIMIT_WINDOW_MS);
  if (timestamps.length >= RATE_LIMIT_MAX) {
    submissionLog.set(ip, timestamps);
    return true;
  }
  timestamps.push(now);
  submissionLog.set(ip, timestamps);
  return false;
}

