<body>
  <h1>Live Word Cloud</h1>
  <form id="wordForm">
    <input type="text" id="wordInput" placeholder="Type a word..." maxlength="30" autocomplete="off" />
    <button type="submit">Add</button>
  </form>
  <div id="error"></div>
  <div id="cloud"></div>

<script>
  const cloudEl = document.getElementById('cloud');
  const formEl = document.getElementById('wordForm');
  const inputEl = document.getElementById('wordInput');
  const errorEl = document.getElementById('error');

  function renderCloud(cloud) {
    cloudEl.innerHTML = '';
    cloud.forEach(function (item) {
      const span = document.createElement('span');
      span.className = 'word';
      span.style.fontSize = item.size + 'px';
      span.textContent = item.word;
      cloudEl.appendChild(span);
    });
  }

  // Polling is the floor: it works even when a proxy on conference wifi
  // buffers or drops the SSE stream entirely. It runs on load and on a
  // fixed interval regardless of SSE state.
  const POLL_INTERVAL_MS = 5000;
  let pollTimer = null;

  function fetchCloudOnce() {
    fetch('/cloud')
      .then(function (res) {
        if (!res.ok) throw new Error('bad response');
        return res.json();
      })
      .then(function (cloud) {
        renderCloud(cloud);
      })
      .catch(function () {
        // ignore transient network errors; next poll or SSE push will retry
      });
  }

  function schedulePoll() {
    if (pollTimer) clearTimeout(pollTimer);
    pollTimer = setTimeout(function () {
      fetchCloudOnce();
      schedulePoll();
    }, POLL_INTERVAL_MS);
  }

  // Initial render must not depend on SSE arriving.
  fetchCloudOnce();
  schedulePoll();

  // SSE is purely an accelerator: when it delivers a fresh snapshot we
  // render it immediately and reset the poll timer so we don't double-fetch
  // right away, but if SSE never connects or gets buffered by a proxy the
  // polling loop above still keeps the page in sync.
  try {
    const source = new EventSource('/events');
    source.onmessage = function (evt) {
      try {
        const cloud = JSON.parse(evt.data);
        renderCloud(cloud);
        schedulePoll();
      } catch (e) {
        // ignore malformed events; polling still covers us
      }
    };
    source.onerror = function () {
      // connection dropped or never established; polling loop is the floor
    };
  } catch (e) {
    // EventSource unsupported; polling loop is the floor
  }

  formEl.addEventListener('submit', function (evt) {
    evt.preventDefault();
    const word = inputEl.value;
    errorEl.textContent = '';
    fetch('/submit', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ word: word })
    }).then(function (res) {
      return res.json().then(function (data) {
        if (!res.ok) {
          errorEl.textContent = data.error || 'Error submitting word';
        } else {
          inputEl.value = '';
          fetchCloudOnce();
        }
      });
    }).catch(function () {
      errorEl.textContent = 'Network error';
    });
  });
</script>
</body>
</html>`;

function broadcastCloud() {
  const cloud = getCloud(state);
  const payload = 'data: ' + JSON.stringify(cloud) + '\n\n';
  for (const res of clients) {
    res.write(payload);
  }
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > 1e6) {
        reject(new Error('body too large'));
        req.destroy();
      }
    });
    req.on('end', () => resolve(raw));
    req.on('error', reject);
  });
}

function getClientIp(req) {
  return req.socket && req.socket.remoteAddress ? req.socket.remoteAddress : 'unknown';
}

const server = http.createServer((req, res) => {
  const { pathname } = new URL(req.url, 'http://localhost');

  if (req.method === 'GET' && pathname === '/') {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(PAGE);
    return;
  }

  if (req.method === 'GET' && pathname === '/cloud') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(getCloud(state)));
    return;
  }

  if (req.method === 'GET' && pathname === '/events') {
    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
    });
    res.write('data: ' + JSON.stringify(getCloud(state)) + '\n\n');
    clients.add(res);
    req.on('close', () => {
      clients.delete(res);
    });
    return;
  }

  if (req.method === 'POST' && pathname === '/submit') {
    const ip = getClientIp(req);
    if (isRateLimited(ip)) {
      res.writeHead(429, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'too many submissions, slow down' }));
      return;
    }
    readBody(req)
      .then((raw) => {
        let body;
        try {
          body = JSON.parse(raw);
        } catch (e) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'invalid JSON' }));
          return;
        }
        const result = addWord(state, body && body.word);
        state = result.state;
        if (result.error) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: result.error }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ word: result.word }));
        broadcastCloud();
      })
      .catch(() => {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'invalid request body' }));
      });
    return;
  }

  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('Not Found');
});

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  server.listen(PORT, () => {
    console.log('Word cloud server listening on port ' + PORT);
  });
}

module.exports = server;

'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { normalizeWord, createState, addWord, getCloud } = require('./wordcloud.js');

test('normalizeWord trims and lowercases', () => {
  assert.strictEqual(normalizeWord('  Hello  '), 'hello');
  assert.strictEqual(normalizeWord('HeLLo World'), 'hello world');
});

test('normalizeWord collapses internal whitespace', () => {
  assert.strictEqual(normalizeWord('foo    bar'), 'foo bar');
  assert.strictEqual(normalizeWord('foo\t\nbar'), 'foo bar');
});

test('normalizeWord strips disallowed characters but keeps letters, numbers, hyphens', () => {
  assert.strictEqual(normalizeWord('c@t!!'), 'ct');
  assert.strictEqual(normalizeWord('well-known2'), 'well-known2');
  assert.strictEqual(normalizeWord('100% cool!'), '100 cool');
});

test('normalizeWord rejects empty input', () => {
  assert.strictEqual(normalizeWord(''), null);
  assert.strictEqual(normalizeWord('   '), null);
  assert.strictEqual(normalizeWord('!!!'), null);
});

test('normalizeWord rejects overlong input (>30 chars)', () => {
  const long = 'a'.repeat(31);
  assert.strictEqual(normalizeWord(long), null);
  const ok = 'a'.repeat(30);
  assert.strictEqual(normalizeWord(ok), ok);
});

test('normalizeWord rejects non-string, non-coercible input', () => {
  assert.strictEqual(normalizeWord(null), null);
  assert.strictEqual(normalizeWord(undefined), null);
  const bad = { toString() { throw new Error('nope'); } };
  assert.strictEqual(normalizeWord(bad), null);
});

test('normalizeWord accepts coercible non-string input', () => {
  assert.strictEqual(normalizeWord(123), '123');
});

test('createState returns fresh empty state', () => {
  const s1 = createState();
  const s2 = createState();
  assert.deepStrictEqual(s1, { counts: {}, total: 0, order: [] });
  s1.counts.foo = 5;
  s1.order.push('foo');
  assert.deepStrictEqual(s2, { counts: {}, total: 0, order: [] });
});

test('addWord does not mutate the input state', () => {
  const state = createState();
  const frozenCopy = JSON.parse(JSON.stringify(state));
  addWord(state, 'cat');
  assert.deepStrictEqual(state, frozenCopy);
});

test('addWord accumulates repeated words correctly', () => {
  let state = createState();
  let result = addWord(state, 'cat');
  state = result.state;
  assert.strictEqual(result.word, 'cat');
  assert.strictEqual(state.counts.cat, 1);

  result = addWord(state, 'Cat');
  state = result.state;
  assert.strictEqual(state.counts.cat, 2);
  assert.strictEqual(state.total, 2);

  result = addWord(state, 'dog');
  state = result.state;
  assert.strictEqual(state.counts.cat, 2);
  assert.strictEqual(state.counts.dog, 1);
  assert.strictEqual(state.total, 3);
});

test('addWord returns error for invalid words without changing counts', () => {
  const state = createState();
  const result = addWord(state, '!!!');
  assert.strictEqual(result.error, 'invalid word');
  assert.strictEqual(result.word, null);
  assert.strictEqual(result.state, state);
  assert.deepStrictEqual(result.state.counts, {});
});

test('getCloud returns empty array for empty state', () => {
  const state = createState();
  assert.deepStrictEqual(getCloud(state), []);
});

test('getCloud sorts by count descending with alphabetical tiebreak', () => {
  let state = createState();
  ['banana', 'apple', 'cherry', 'apple', 'banana', 'apple'].forEach((w) => {
    state = addWord(state, w).state;
  });
  // apple: 3, banana: 2, cherry: 1
  const cloud = getCloud(state);
  assert.deepStrictEqual(cloud.map((e) => e.word), ['apple', 'banana', 'cherry']);

  let state2 = createState();
  ['zebra', 'apple'].forEach((w) => {
    state2 = addWord(state2, w).state;
  });
  const cloud2 = getCloud(state2);
  // both count 1, alphabetical tiebreak
  assert.deepStrictEqual(cloud2.map((e) => e.word), ['apple', 'zebra']);
});

test('getCloud produces sizes within bounds and monotonic with count', () => {
  let state = createState();
  for (let i = 0; i < 5; i++) state = addWord(state, 'popular').state;
  state = addWord(state, 'rare').state;

  const cloud = getCloud(state, { minSize: 10, maxSize: 50 });
  const popular = cloud.find((e) => e.word === 'popular');
  const rare = cloud.find((e) => e.word === 'rare');

  assert.ok(popular.size >= 10 && popular.size <= 50);
  assert.ok(rare.size >= 10 && rare.size <= 50);
  assert.ok(popular.size > rare.size);
  assert.strictEqual(popular.size, 50); // max count maps to maxSize
});

test('getCloud uses default opts when none provided', () => {
  let state = createState();
  state = addWord(state, 'solo').state;
  const cloud = getCloud(state);
  assert.strictEqual(cloud[0].size, 48); // only word -> max count -> maxSize default
});

test('addWord bounds the number of distinct tracked words', () => {
  let state = createState();
  // Add far more distinct words than the internal cap allows.
  const totalDistinctSubmitted = 1200;
  for (let i = 0; i < totalDistinctSubmitted; i++) {
    state = addWord(state, `word${i}`).state;
  }
  const distinctTracked = Object.keys(state.counts).length;
  assert.ok(
    distinctTracked <= 1000,
    `expected at most 1000 distinct words tracked, got ${distinctTracked}`
  );
  assert.ok(distinctTracked > 0);
  // order bookkeeping should stay in sync with counts
  assert.strictEqual(state.order.length, distinctTracked);
});

test('addWord eviction favors keeping higher-count words over low-count ones', () => {
  let state = createState();
  // Fill up to the cap with unique words, then push one word's count high.
  for (let i = 0; i < 999; i++) {
    state = addWord(state, `filler${i}`).state;
  }
  // Give "popular" a high count while it's still within the cap.
  for (let i = 0; i < 10; i++) {
    state = addWord(state, 'popular').state;
  }
  assert.ok(Object.keys(state.counts).length <= 1000);

  // Now push many brand-new distinct words past the cap; eviction should
  // remove low-count filler words rather than the high-count "popular" one.
  for (let i = 0; i < 500; i++) {
    state = addWord(state, `newword${i}`).state;
  }

  assert.ok(Object.keys(state.counts).length <= 1000);
  assert.strictEqual(state.counts.popular, 10);
});

const test = require('node:test');
const assert = require('node:assert');
const http = require('node:http');
const server = require('./server.js');

function startServer() {
  return new Promise((resolve) => {
    server.listen(0, () => {
      resolve(server.address().port);
    });
  });
}

function request(port, options, body) {
  return new Promise((resolve, reject) => {
    const req = http.request(
      Object.assign({ hostname: 'localhost', port }, options),
      (res) => {
        let data = '';
        res.on('data', (chunk) => {
          data += chunk;
        });
        res.on('end', () => {
          resolve({ statusCode: res.statusCode, headers: res.headers, body: data });
        });
      }
    );
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

function postWord(port, word) {
  const body = JSON.stringify({ word });
  return request(
    port,
    {
      method: 'POST',
      path: '/submit',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
    },
    body
  );
}

// Opens a persistent SSE connection and resolves each time a new `data: `
// event is received, up to `count` events, collecting them in an array.
function collectSseEvents(port, count) {
  return new Promise((resolve, reject) => {
    const events = [];
    let buffer = '';
    const req = http.request(
      { hostname: 'localhost', port, method: 'GET', path: '/events' },
      (res) => {
        res.on('data', (chunk) => {
          buffer += chunk.toString();
          let idx;
          while ((idx = buffer.indexOf('\n\n')) !== -1) {
            const raw = buffer.slice(0, idx);
            buffer = buffer.slice(idx + 2);
            if (raw.startsWith('data: ')) {
              try {
                events.push(JSON.parse(raw.slice('data: '.length)));
              } catch (e) {
                // ignore malformed chunk
              }
            }
            if (events.length >= count) {
              res.destroy();
              resolve({ events, req });
              return;
            }
          }
        });
        res.on('error', () => {});
      }
    );
    req.on('error', reject);
    req.end();
  });
}

let port;

test.before(async () => {
  port = await startServer();
});

test.after(() => {
  server.close();
});

test('GET / returns 200 text/html containing <html', async () => {
  const res = await request(port, { method: 'GET', path: '/' });
  assert.strictEqual(res.statusCode, 200);
  assert.match(res.headers['content-type'], /text\/html/);
  assert.match(res.body, /<html/);
});

test('GET /cloud returns the current cloud as JSON (independent of SSE)', async () => {
  const res = await request(port, { method: 'GET', path: '/cloud' });
  assert.strictEqual(res.statusCode, 200);
  assert.match(res.headers['content-type'], /application\/json/);
  const parsed = JSON.parse(res.body);
  assert.ok(Array.isArray(parsed));
});

test('POST /submit with valid word returns 200 and normalized word', async () => {
  const res = await postWord(port, '  Cat  ');
  assert.strictEqual(res.statusCode, 200);
  const parsed = JSON.parse(res.body);
  assert.strictEqual(parsed.word, 'cat');
});

test('POST /submit with invalid word returns 400', async () => {
  const res = await postWord(port, '!!!');
  assert.strictEqual(res.statusCode, 400);
  const parsed = JSON.parse(res.body);
  assert.ok(parsed.error);
});

test('POST /submit with invalid word does not change the broadcast cloud state', async () => {
  const before = await request(port, { method: 'GET', path: '/cloud' });
  const beforeCloud = JSON.parse(before.body);

  const res = await postWord(port, '###');
  assert.strictEqual(res.statusCode, 400);

  const after = await request(port, { method: 'GET', path: '/cloud' });
  const afterCloud = JSON.parse(after.body);

  assert.deepStrictEqual(afterCloud, beforeCloud);
});

test('GET /events responds with SSE content-type and first chunk is valid JSON array', async () => {
  const result = await new Promise((resolve, reject) => {
    const req = http.request(
      { hostname: 'localhost', port, method: 'GET', path: '/events' },
      (res) => {
        let firstChunk = null;
        res.on('data', (chunk) => {
          if (firstChunk === null) {
            firstChunk = chunk.toString();
            res.destroy();
            resolve({ headers: res.headers, firstChunk });
          }
        });
        res.on('error', () => {});
      }
    );
    req.on('error', reject);
    req.end();
  });

  assert.match(result.headers['content-type'], /text\/event-stream/);
  assert.ok(result.firstChunk.startsWith('data: '));
  const jsonStr = result.firstChunk.slice('data: '.length).trim();
  const parsed = JSON.parse(jsonStr);
  assert.ok(Array.isArray(parsed));
});

test('two POSTs of the same word broadcast a cloud where its count is 2 to a connected SSE client', async () => {
  const uniqueWord = 'zebra' + Date.now();
  const ssePromise = collectSseEvents(port, 3); // initial snapshot + 2 broadcasts

  // give the SSE connection a moment to register before posting
  await new Promise((resolve) => setTimeout(resolve, 50));

  const res1 = await postWord(port, uniqueWord);
  assert.strictEqual(res1.statusCode, 200);
  const res2 = await postWord(port, uniqueWord);
  assert.strictEqual(res2.statusCode, 200);

  const { events } = await ssePromise;
  assert.strictEqual(events.length, 3);
  const finalCloud = events[events.length - 1];
  const entry = finalCloud.find((e) => e.word === uniqueWord.toLowerCase());
  assert.ok(entry, 'expected word to appear in broadcast cloud');
  assert.strictEqual(entry.count, 2);
});

test('POST /submit is rate limited past a threshold, returning 429', async () => {
  const results = [];
  for (let i = 0; i < 20; i++) {
    results.push(await postWord(port, 'ratelimitword' + i));
  }
  const limited = results.filter((r) => r.statusCode === 429);
  assert.ok(limited.length > 0, 'expected at least one 429 after flooding /submit');
  limited.forEach((r) => {
    const parsed = JSON.parse(r.body);
    assert.ok(parsed.error);
  });
});

